local SandConditionerMaker = {}
local PRODUCTS = {
    iron_sandconditioner = { name = "Železni kondicioner za livarski pesek", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni kondicioner za livarski pesek za livarje." },
    bronze_sandconditioner = { name = "Bronast kondicioner za livarski pesek", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast kondicioner za livarski pesek za livarje." },
    silver_sandconditioner = { name = "Srebrn kondicioner za livarski pesek", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn kondicioner za livarski pesek za livarje." },
    gilded_sandconditioner = { name = "Pozlačen kondicioner za livarski pesek", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen kondicioner za livarski pesek za livarje." },
    jewel_set_sandconditioner = { name = "Draguljast kondicioner za livarski pesek", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast kondicioner za livarski pesek za livarje." },
    royal_sovereign_sandconditioner = { name = "Kraljevski suveren kondicioner za livarski pesek", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren kondicioner za livarski pesek z biseri za krono." },
}
local BUILDINGS = {
    sandconditioner_workshop = { name = "Sandconditioner delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sandconditioner_house = { name = "Sandconditioner hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sandconditioner_atelier = { name = "Mojstrski sandconditioner atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sandconditioner_palace = { name = "Suverena sandconditioner palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SandConditionerMaker.ironStock=18; SandConditionerMaker.bronzeStock=14; SandConditionerMaker.woodStock=10; SandConditionerMaker.leatherStock=8; SandConditionerMaker.silverStock=8; SandConditionerMaker.goldStock=6; SandConditionerMaker.jewelStock=4; SandConditionerMaker.pearlStock=4
SandConditionerMaker.productStock = {}; SandConditionerMaker.buildings = {}; SandConditionerMaker.maker = nil; SandConditionerMaker.activeMaking = {}; SandConditionerMaker.totalProducts = 0; SandConditionerMaker.dayTimer = 0
function SandConditionerMaker.init() SandConditionerMaker.ironStock=18; SandConditionerMaker.bronzeStock=14; SandConditionerMaker.woodStock=10; SandConditionerMaker.leatherStock=8; SandConditionerMaker.silverStock=8; SandConditionerMaker.goldStock=6; SandConditionerMaker.jewelStock=4; SandConditionerMaker.pearlStock=4; SandConditionerMaker.productStock={}; SandConditionerMaker.buildings={}; SandConditionerMaker.maker=nil; SandConditionerMaker.activeMaking={}; SandConditionerMaker.totalProducts=0; SandConditionerMaker.dayTimer=0; print("[SandConditionerMaker] Royal Sand Conditioner Maker System initialized (6 products, 4 buildings)") end
function SandConditionerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SandConditionerMaker.maker={name=n or ("Kondicionar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kondicionar najet: %s (spretnost: %d)",SandConditionerMaker.maker.name,s),"success") end; return true end
function SandConditionerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SandConditionerMaker.build(id) local ok,e=SandConditionerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SandConditionerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SandConditionerMaker.getQualityBonus() local b=0; for _,bd in ipairs(SandConditionerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SandConditionerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SandConditionerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SandConditionerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SandConditionerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SandConditionerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SandConditionerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SandConditionerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SandConditionerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SandConditionerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SandConditionerMaker.buildings==0 then return false,"Potrebna kondicionerna delavnica" end; if not SandConditionerMaker.maker then return false,"Potreben kondicionar" end; return true end
function SandConditionerMaker.make(pt,qty) qty=qty or 1; local ok,e=SandConditionerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SandConditionerMaker.ironStock=SandConditionerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SandConditionerMaker.bronzeStock=SandConditionerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SandConditionerMaker.woodStock=SandConditionerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SandConditionerMaker.leatherStock=SandConditionerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SandConditionerMaker.silverStock=SandConditionerMaker.silverStock-d.silverCost*qty end; if d.goldCost then SandConditionerMaker.goldStock=SandConditionerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SandConditionerMaker.jewelStock=SandConditionerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SandConditionerMaker.pearlStock=SandConditionerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SandConditionerMaker.maker then t=math.max(1,t-math.floor(SandConditionerMaker.maker.skill/13)) end; table.insert(SandConditionerMaker.activeMaking,{id="sandconditioner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SandConditionerMaker.completeMaking(m) local q=1.0+(SandConditionerMaker.getQualityBonus()/100); if SandConditionerMaker.maker then q=q+(SandConditionerMaker.maker.skill/140) end; q=math.min(2.5,q); SandConditionerMaker.productStock[m.productType]=(SandConditionerMaker.productStock[m.productType] or 0)+m.quantity; SandConditionerMaker.totalProducts=SandConditionerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SandConditionerMaker.maker then SandConditionerMaker.maker.itemsMade=SandConditionerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SandConditionerMaker.maker.skill=math.min(100,SandConditionerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kondicioner izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sandconditioner.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SandConditionerMaker.update(dt) if not _G.state then return end; SandConditionerMaker.dayTimer=SandConditionerMaker.dayTimer+dt; if SandConditionerMaker.dayTimer>=30 then SandConditionerMaker.dayTimer=0; for i=#SandConditionerMaker.activeMaking,1,-1 do local m=SandConditionerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SandConditionerMaker.completeMaking(m); table.remove(SandConditionerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SandConditionerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SandConditionerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SandConditionerMaker.getStats() return {ironStock=SandConditionerMaker.ironStock,bronzeStock=SandConditionerMaker.bronzeStock,woodStock=SandConditionerMaker.woodStock,leatherStock=SandConditionerMaker.leatherStock,silverStock=SandConditionerMaker.silverStock,goldStock=SandConditionerMaker.goldStock,jewelStock=SandConditionerMaker.jewelStock,pearlStock=SandConditionerMaker.pearlStock,productStock=SandConditionerMaker.productStock,numBuildings=#SandConditionerMaker.buildings,hasMaker=SandConditionerMaker.maker~=nil,makerName=SandConditionerMaker.maker and SandConditionerMaker.maker.name or "—",makerSkill=SandConditionerMaker.maker and SandConditionerMaker.maker.skill or 0,activeMaking=#SandConditionerMaker.activeMaking,totalProducts=SandConditionerMaker.totalProducts} end
return SandConditionerMaker
